<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Holder\TemplateAssetTypeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateAssetTypeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateAssetTypeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getType returns null on a freshly created holder.
     */
    public function testTypeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetTypeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTypeAssigned());
        $this->assertNull($holder->getType());
    }
}
class ImplWithTemplateAssetTypeAttributeHolderUnitTest
{
    use TemplateAssetTypeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTypeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultType();
    }
}
